  for(const row of entries){if(!groups.has(row.provider))groups.set(row.provider,new Set());groups.get(row.provider).add(hubConfigurationKey(row))}
  rail.hidden=groups.size<2;
  rail.innerHTML=groups.size?`<span class="provider-rail-label">按模型公司浏览</span><div class="provider-buttons">${[...groups].sort((a,b)=>b[1].size-a[1].size).map(([provider,configs])=>`<button type="button" data-hub-provider="${esc(provider)}" aria-pressed="${hubState.query.toLowerCase()===provider.toLowerCase()}">${typeof brandBadge==='function'?brandBadge(provider):esc(provider)}<small>${configs.size}</small></button>`).join('')}</div>`:'';
